import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import api from '../api'; // Assuming api.js is configured correctly for Axios requests
import './Auth.css';

const Register = () => {
  const [form, setForm] = useState({ username: '', password: '' });
  const [message, setMessage] = useState('');
  const [success, setSuccess] = useState(null);
  const navigate = useNavigate();

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      const response = await api.post('/auth/register', form); // Make sure this route matches your backend
      setSuccess(true);
      setMessage('Registration Successful! Redirecting...');
      setTimeout(() => {
        navigate('/login'); // After 2 seconds, redirect to login page
      }, 2000);
    } catch (err) {
      setSuccess(false);
      setMessage(err.response?.data?.message || 'Registration failed');
    }
  };

  return (
    <div className="auth-container">
      <h2>Register</h2>
      <form className="auth-form" onSubmit={handleSubmit}>
        <input 
          type="text" 
          name="username" 
          placeholder="Username" 
          value={form.username} 
          onChange={(e) => setForm({ ...form, username: e.target.value })}
          required
        />
        <input 
          type="password" 
          name="password" 
          placeholder="Password" 
          value={form.password} 
          onChange={(e) => setForm({ ...form, password: e.target.value })}
          required
        />
        <button type="submit">Register</button>
      </form>
      {message && (
        <p className={`auth-message ${success ? 'success' : 'error'}`}>
          {message}
        </p>
      )}
    </div>
  );
};

export default Register;
